package config

import (
	"fmt"
	"strings"

	"gopkg.in/yaml.v3"
)

// ParseUALabCodexYAML strictly parses a pasted "# Generated by UALab" YAML block
// into CodexHeaderDefaults. It rejects "auto" and requires an explicit User-Agent.
func ParseUALabCodexYAML(raw string) (CodexHeaderDefaults, error) {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		return CodexHeaderDefaults{}, fmt.Errorf("paste the %s YAML block generated by UALab", UALabGeneratedMarker)
	}
	if !strings.Contains(trimmed, UALabGeneratedMarker) {
		return CodexHeaderDefaults{}, fmt.Errorf("input must contain the %q header produced by UALab", UALabGeneratedMarker)
	}

	var v8Doc struct {
		OAuth struct {
			Providers struct {
				Codex struct {
					HeaderDefaults CodexHeaderDefaults `yaml:"header-defaults"`
				} `yaml:"codex"`
			} `yaml:"providers"`
		} `yaml:"oauth"`
		Legacy CodexHeaderDefaults `yaml:"codex-header-defaults"`
	}
	if err := yaml.Unmarshal([]byte(trimmed), &v8Doc); err != nil {
		return CodexHeaderDefaults{}, fmt.Errorf("invalid UALab YAML: %w", err)
	}

	hd := v8Doc.OAuth.Providers.Codex.HeaderDefaults
	if hd.UserAgent == "" && v8Doc.Legacy.UserAgent != "" {
		hd = v8Doc.Legacy
	}

	tmpCfg := &Config{CodexHeaderDefaults: hd}
	tmpCfg.SanitizeCodexHeaderDefaults()
	hd = tmpCfg.CodexHeaderDefaults

	if hd.UserAgent == "" {
		return CodexHeaderDefaults{}, fmt.Errorf("UALab YAML is missing oauth.providers.codex.header-defaults.user-agent")
	}
	if err := tmpCfg.ValidateUserAgents(); err != nil {
		return CodexHeaderDefaults{}, err
	}
	return hd, nil
}
